import{z as A,x as l,o as r,c as p,q as E,j as i,D as e,d as n,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"数量方程与货币中性","description":"","frontmatter":{"title":"数量方程与货币中性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/quantity-theory.md","filePath":"econ/quantity-theory.md","lastUpdated":1791063341000}'),d={name:"econ/quantity-theory.md"};function B(h,a,y,P,m,M){const t=l("Mermaid");return r(),p("div",null,[a[2]||(a[2]=E('<h1 id="数量方程与货币中性" tabindex="-1">数量方程与货币中性 <a class="header-anchor" href="#数量方程与货币中性" aria-label="Permalink to &quot;数量方程与货币中性&quot;">​</a></h1><div class="epigraph"><p>数量方程先是交易的会计：货币存量乘周转次数，对着名义支出；把它读成「货币决定物价」，已经加入了速度与产出的行为假设。</p><footer>—— Fisher, The Purchasing Power of Money；Friedman, The Quantity Theory of Money: A Restatement, 1956</footer></div><p><a href="/econ/lagos-wright">上一课</a>（Lagos–Wright 新货币主义）。在此之上， \\(M\\) 钉成支付层次，而不是财富清单。本课的缺口是：\\(M\\) 与已经缩减过的 \\(y\\)、价格指数 \\(P\\) 如何写成一句话，以及这句话在什么条件下变成<strong>长期中性</strong>。Friedman 的重述把数量方程从恒等推进到货币需求；自然率课已经说过 \\(u^*\\) 不受名义水平支配，本课把同一逻辑写到 \\(P\\) 上。铸币税是下一课对「谁从 \\(M\\) 增长里抽税」的缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易需要支付。若每笔支出都用货币结清，可以写</p> \\[MV \\equiv Py, \\]<p>\\(V\\) 为流通速度，\\(y\\) 为实际交易或实际产出（口径必须声明）。等号在定义 \\(V=Py/M\\) 时是恒等。理论从恒等变成数量<strong>论</strong>，当且仅当再假设：\\(V\\) 由支付习惯与利率稳定地决定，\\(y\\) 在充分就业路径上由实物因素决定。那时 \\(M\\) 的永久增加主要抬 \\(P\\)。</p><p>Friedman（1956）把这改写成货币需求：实际余额 \\(M/P\\) 是 \\(y\\) 与机会成本（名义利率）的函数。中性说的是：\\(M\\) 的水平不改变稳态的相对价格与 \\(y^*\\)；它不否认过渡期 \\(y\\) 会动。Lucas 后来把预期写进这条短期缺口。</p><p><span class="marginnote">数字实例：\\(M=20\\) 万亿、\\(V=5\\)，则 \\(Py=100\\) 万亿；若 \\(y=10\\) 万亿单位，\\(P=10\\)。\\(M\\) 翻倍而 \\(V\\)、\\(y\\) 不动，\\(P\\) 就跟着翻倍到 20——「数量论」的全部内容就是把「\\(V\\)、\\(y\\) 不动」当成行为假设加进来。</span></p><p><span class="marginnote">古典二分：名义变量定绝对价格，实物变量定 \\(y\\) 与相对价格。超中性更强：连 \\(M\\) 的<strong>增长率</strong>也不影响实物稳态。有限现金、通胀税会打破超中性，那是铸币税课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>会计形式先写开。\\(P\\) 用<a href="/econ/price-index-real">平减或 CPI</a>，\\(y\\) 用实际产出或交易量。\\(V\\) 随支付技术上升（更快的清算），也随名义利率上升（持币机会成本高则少持、周转加快）。Friedman 的需求函数把 \\(V\\) 的稳定写成经验命题，不是恒真。</p><p><span class="marginnote">直觉类比：流通速度像同一张百元钞票一年换了几次手——你付给店主，店主发工资，工资再变成消费。一年里这 100 元完成了几笔支出，\\(V\\) 就是几；扫码支付让它换手更快，\\(V\\) 自然上行。</span></p><p>长期：在 \\(u^*\\)、\\(y^*\\) 上，\\(M\\) 的一次水平平移使 \\(P\\) 同比例平移，名义利率的费雪成分 \\(\\mathrm{i}\\approx r+\\pi^e\\) 里，\\(r\\) 由实物与时间偏好决定。短期：\\(V\\) 或价格粘性使 \\(M\\) 变动先打到 \\(y\\)，这是后课 IS–LM 与新凯恩斯的入口，本课只划界。</p>',14)),(r(),i(s,null,{default:e(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22MV%20%E2%89%A1%20Py%20%E6%81%92%E7%AD%89%22%5D%20--%3E%20DEM%5B%22%E8%B4%A7%E5%B8%81%E9%9C%80%E6%B1%82%EF%BC%9AM%2FP%20%3D%20L(y%2Ci)%22%5D%0A%20%20DEM%20--%3E%20NEUT%5B%22%E9%95%BF%E6%9C%9F%EF%BC%9Ay%E2%86%92y*%EF%BC%8CM%20%E8%BF%9B%20P%22%5D%0A%20%20DEM%20--%3E%20SR%5B%22%E7%9F%AD%E6%9C%9F%EF%BC%9AV%20%E6%88%96%E7%B2%98%E6%80%A7%20%E2%86%92%20y%20%E5%8F%AF%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>货币存量规则（Friedman 的 \\(k\\)%）是把中性当成政策纪律：不要用 \\(M\\) 去钉住失业。规则是否时间一致，是更后的课。</p><h3 id="中性不是「货币无用」" tabindex="-1">中性不是「货币无用」 <a class="header-anchor" href="#中性不是「货币无用」" aria-label="Permalink to &quot;中性不是「货币无用」&quot;">​</a></h3><p>中性否定的是用名义工具永久改变 \\(y^*\\)。支付系统仍能改变 \\(V\\) 与福利（持币成本）。汇率与开放在蒙代尔课才出现；本课封闭。也不要把数量方程写成加密资产的恒真预言：\\(M\\) 的口径一变，\\(V\\) 就吸收误差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若价格完全灵活、预期正确、市场出清，多出来的 \\(M\\) 只是更高的单位价格：相对价格和配置回到原实物均衡。这是与<a href="/econ/walrasian-equilibrium">瓦尔拉斯</a>同一逻辑的名义加层。若有人暂时误读一般物价为相对价格变动，就业可以偏离 \\(u^*\\)——Friedman（1968）与 Lucas 的岛屿模型走的就是这条预期缺口，细节在菲利普斯课。</p><p>速度崩溃（持币骤增）时，同样的 \\(M\\) 对不上原来的 \\(Py\\)：名义支出掉下来。这是恒等仍成立、数量论的稳定 \\(V\\) 暂时失效。后课零下限会再遇到「想持有货币而利率无法再降」。</p>',6)),(r(),i(s,null,{default:e(()=>[o(t,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20LR%0A%20%20MUP%5B%22M%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20Q%5B%22P%20%E6%B6%A8%E5%A4%9A%E5%B0%91%3F%20%E7%9C%8B%E4%B8%A4%E4%B8%AA%E6%91%86%E5%8A%A8%E9%A1%B9%22%5D%0A%20%20Q%20--%3E%20VQ%5B%22V%20%E7%A8%B3%E5%90%97%3F%20%E6%94%AF%E4%BB%98%E4%B9%A0%E6%83%AF%E4%B8%8E%E5%88%A9%E7%8E%87%22%5D%0A%20%20Q%20--%3E%20YQ%5B%22y%20%E5%8A%A8%E5%90%97%3F%20%E7%B2%98%E6%80%A7%E4%B8%8E%E9%A2%84%E6%9C%9F%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20VQ%20--%3E%20VOK%5B%22V%20%E7%A8%B3%3A%20M%20%E7%9A%84%E5%8E%8B%E5%8A%9B%E5%85%A8%E4%BC%A0%E4%B8%8B%E5%8E%BB%22%5D%0A%20%20VQ%20--%3E%20VCRASH%5B%22V%20%E5%B4%A9%3A%20%E6%8C%81%E5%B8%81%E9%AA%A4%E5%A2%9E%2C%20%E5%90%8D%E4%B9%89%E6%94%AF%E5%87%BA%E6%8E%89%22%5D%0A%20%20YQ%20--%3E%20YOK%5B%22%E9%95%BF%E6%9C%9F%20y%3Dy*%3A%20M%20%E5%85%A8%E8%BF%9B%20P%22%5D%0A%20%20YQ%20--%3E%20YMOVE%5B%22%E7%9F%AD%E6%9C%9F%20y%20%E5%8F%AF%E5%8A%A8%3A%20M%20%E5%85%88%E6%89%93%E5%88%B0%E4%BA%A7%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>\\(i\\) 是持币的机会成本：\\(i\\) 升则 \\(L\\) 降、\\(V\\) 升。把 \\(V\\) 当技术常数，会在利率大幅变动时误读 \\(M\\) 与 \\(P\\)。层次选错会把替代当成「数量论失败」——回到上一课声明 \\(M\\) 是哪一层。</p><p><span class="marginnote">常见误区：初学者容易把 \\(MV=Py\\) 当成每月通胀的预言机。恒等式本身永远成立，会「失败」的只是 \\(V\\) 与 \\(y\\) 稳定这两个行为假设——所以季度 CPI 读不出 \\(M2\\)，趋势才看得出方向。</span></p><p><span class="marginnote">超中性：改变 \\(M\\) 的增长率也不影响实际变量。通胀税会改变实际余额与资本积累，超中性往往失败。本课钉中性，超中性留给铸币税。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>数量方程不是通胀的唯一理论：相对价格冲击、间接税、汇率转嫁都会动 \\(P\\)。本课主张的是长期里持续的通胀要有 \\(M\\) 增长配合，不是每一季的 CPI 都能从 \\(M2\\) 读出。也不要把公司现金管理写成宏观 \\(V\\)。外汇 CIP 在<a href="/quant/irp">量化栏</a>，不是 \\(MV=Py\\) 的开放版。</p><p>后课默认：谈通胀趋势时，\\(M\\) 与 \\(P\\) 同方向；谈 \\(y^*\\) 时货币水平中性。下一课问政府能否靠印钞征税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(MV=Py\\) 先是定义 \\(V\\) 的会计；数量论加上 \\(V\\)、\\(y\\) 的行为。</li><li>长期中性：\\(M\\) 定 \\(P\\)，不定 \\(y^*\\)。</li><li>超中性可被通胀税打破。</li><li>\\(V\\) 随 \\(i\\) 与支付技术而变，不是自然常数。</li><li>短期非中性留给粘性与预期。</li><li>出处：Fisher《货币的购买力》；Friedman 1956 重述；中性与自然率见 Friedman, AER 1968。</li></ul>',8))])}const u=A(d,[["render",B]]);export{c as __pageData,u as default};
